internal sealed partial class Upper() : Executor("Upper")
{
    [MessageHandler]
    private ValueTask<string> HandleAsync(string message, IWorkflowContext ctx)
        => ValueTask.FromResult(message.ToUpperInvariant());   // return value is sent on
}

var upper = new Upper();
WorkflowBuilder builder = new(upper);
builder.AddEdge(upper, validator);
builder.AddFanInBarrierEdge(sources: [w1, w2, w3], target: aggregator);
var workflow = builder.Build();

StreamingRun run = await InProcessExecution.RunStreamingAsync(workflow, input);
await foreach (WorkflowEvent e in run.WatchStreamAsync())
    if (e is WorkflowOutputEvent o) Console.WriteLine(o.Data);
